-- ============================================================
-- Migration v10: IoT reading provenance
-- ============================================================
USE poultry_ecommerce;

-- Every row in iot_readings now carries where it came from:
--   seed      = historical demo data that was already in the table
--   sensor    = a real device upload (api/iot_upload.php)
--   simulated = generated by the cold-chain simulator (api/iot_simulate.php)
--   alert     = a hot excursion recorded when a provider triggers an alert
ALTER TABLE iot_readings
  ADD COLUMN source ENUM('seed','sensor','simulated','alert') NOT NULL DEFAULT 'sensor' AFTER status;

-- The rows that existed before this migration are the historical demo data.
-- The date cut-off keeps the statement idempotent: readings uploaded by a
-- real device afterwards keep source = 'sensor'.
UPDATE iot_readings SET source = 'seed'
 WHERE source = 'sensor' AND recorded_at < '2026-10-20 00:00:00';
